def merge_intervals(intervals):
    """
    Merge all overlapping or touching closed integer intervals and
    return a sorted list of the resulting intervals.
    The input list is never mutated.
    """
    if not intervals:
        return []

    # Create a sorted copy of the intervals
    sorted_intervals = sorted((list(it) for it in intervals), key=lambda x: x[0])

    merged = []
    for start, end in sorted_intervals:
        if not merged:
            merged.append([start, end])
        else:
            last_start, last_end = merged[-1]
            if end <= last_end:
                # Current interval is fully contained; nothing to do
                continue
            if start <= last_end:
                # Overlap or touch: extend the last interval if needed
                merged[-1][1] = max(last_end, end)
            else:
                merged.append([start, end])

    return merged

def toposort(nodes, edges):
    from heapq import heapify, heappop, heappush

    # Ensure input is not mutated
    node_set = set(nodes)

    # Build the graph, deduplicate edges and compute indegrees
    indegree = {n: 0 for n in nodes}
    adjacency = {n: set() for n in nodes}
    seen = set()

    for s, d in edges:
        if s == d:
            raise ValueError("Self loop detected")
        if (s, d) in seen:
            continue
        seen.add((s, d))
        adjacency[s].add(d)
        indegree[d] += 1

    # Initialize priority queue with all nodes of indegree 0
    heap = [n for n in nodes if indegree[n] == 0]
    heapify(heap)

    result = []
    while heap:
        n = heappop(heap)
        result.append(n)
        for nb in adjacency[n]:
            indegree[nb] -= 1
            if indegree[nb] == 0:
                heappush(heap, nb)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result
